package com.laundrylounge.app;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Color;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.text.InputType;
import android.util.Base64;
import android.view.Gravity;
import android.view.View;
import android.view.WindowInsets;
import android.widget.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Arrays;
import java.util.Locale;

public class MainActivity extends Activity {
    public Store store;
    private String page="Home";
    private static final int SCAN=71, LOGO=72, RESTORE=73;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::navigateBack);getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);try{store=new Store(this);render();}catch(Exception failure){recovery(failure.getMessage());}}
    public JSONObject snapshot(){return store.snapshot();}
    public boolean save(JSONObject next){try{store.save(next);render();toast("Saved on this phone");return true;}catch(Exception failure){error(failure.getMessage());return false;}}
    public void error(String message){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("A little attention needed").setMessage(message==null?"Please try again.":message).setPositiveButton("OK",null).show());}
    public void toast(String message){runOnUiThread(()->Toast.makeText(this,message,Toast.LENGTH_SHORT).show());}
    public void openOrder(String id){OrderScreens.showDetail(this,id);}
    public void newOrder(){OrderScreens.showNew(this);}
    public void scan(){startActivityForResult(new Intent(this,ScanActivity.class),SCAN);}
    private void go(String target){page=target;render();}
    private void insets(LinearLayout root){root.setOnApplyWindowInsetsListener((v,w)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=w.getInsets(WindowInsets.Type.systemBars());top=bars.top;bottom=bars.bottom;}else{top=w.getSystemWindowInsetTop();bottom=w.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return w;});}
    private void render(){
        if(store==null)return;JSONObject state=snapshot();JSONObject settings=state.optJSONObject("settings");LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);insets(root);
        LinearLayout header=Ui.row(this);header.setPadding(Ui.dp(this,18),Ui.dp(this,12),Ui.dp(this,18),Ui.dp(this,12));header.setBackgroundColor(Color.WHITE);ImageView logo=new ImageView(this);logo.setImageResource(com.laundrylounge.app.R.drawable.laundry_logo);String own=settings.optString("logo","");if(!own.isEmpty())try{byte[] bytes=Base64.decode(own.substring(own.indexOf(',')+1),Base64.DEFAULT);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image!=null)logo.setImageBitmap(image);}catch(Exception ignored){}logo.setScaleType(ImageView.ScaleType.FIT_CENTER);header.addView(logo,new LinearLayout.LayoutParams(Ui.dp(this,43),Ui.dp(this,43)));LinearLayout brand=Ui.column(this);brand.setPadding(Ui.dp(this,10),0,0,0);brand.addView(Ui.text(this,settings.optString("businessName","Laundry Lounge"),18,Ui.INK,true));brand.addView(Ui.text(this,"A LITTLE EXTRA CARE, EVERY DAY",8,Ui.MUTED,false));header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button gear=Ui.button(this,"⚙",()->go("Settings"),true);header.addView(gear,new LinearLayout.LayoutParams(Ui.dp(this,43),Ui.dp(this,43)));root.addView(header);
        View body;switch(page){case "Orders":body=OrderScreens.orders(this);break;case "Customers":body=BusinessScreens.customers(this);break;case "Expenses":body=BusinessScreens.expenses(this);break;case "Reports":body=BusinessScreens.reports(this);break;case "Settings":body=BusinessScreens.settings(this);break;case "More":body=more();break;default:body=home();}
        root.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=Ui.row(this);nav.setPadding(Ui.dp(this,9),Ui.dp(this,7),Ui.dp(this,9),Ui.dp(this,8));nav.setBackgroundColor(Color.WHITE);for(String tab:new String[]{"Home","Orders","Customers","More"}){boolean selected=page.equals(tab)||(tab.equals("More")&&Arrays.asList("Reports","Expenses","Settings").contains(page));Button button=Ui.button(this,tab,()->go(tab),true);button.setTextSize(12);button.setBackground(Ui.background(selected?Color.rgb(233,245,239):Color.WHITE,0,this,11));button.setTextColor(selected?Ui.TEAL:Ui.MUTED);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Ui.dp(this,48),1);lp.setMargins(Ui.dp(this,3),0,Ui.dp(this,3),0);nav.addView(button,lp);}root.addView(nav);setContentView(root);root.requestApplyInsets();
    }
    private LinearLayout body(){LinearLayout body=Ui.column(this);int p=Ui.dp(this,20);body.setPadding(p,p,p,p);return body;}
    private View more(){LinearLayout b=body();b.addView(Ui.title(this,"Your daily toolkit."));b.addView(Ui.text(this,"The details that keep your lounge running.",13,Ui.MUTED,false));Ui.gap(this,b,20);for(String target:new String[]{"Reports","Expenses","Settings"}){LinearLayout card=Ui.card(this);card.addView(Ui.text(this,target,18,Ui.INK,true));card.addView(Ui.text(this,target.equals("Reports")?"Collections, services and spending":target.equals("Expenses")?"Keep things balanced":"Business details, logo and backups",12,Ui.MUTED,false));card.setOnClickListener(v->go(target));card.setMinimumHeight(Ui.dp(this,88));b.addView(card);}LinearLayout note=Ui.card(this);note.addView(Ui.text(this,"Made for Laundry Lounge",17,Ui.INK,true));note.addView(Ui.text(this,"Records stay privately on this phone. Export backups in Settings. Bills, tags, scanning and sharing use Android's native controls.",13,Ui.MUTED,false));b.addView(note);return Ui.scroll(this,b);}
    private View home(){JSONObject state=snapshot();JSONArray orders=Records.array(state,"orders");LinearLayout b=body();b.addView(Ui.text(this,LocalDate.now().format(DateTimeFormatter.ofPattern("EEEE, d MMM",Locale.ENGLISH)).toUpperCase(Locale.ROOT),10,Ui.MUTED,true));Ui.gap(this,b,10);b.addView(Ui.title(this,"A fresh start.\nA smoother day."));b.addView(Ui.text(this,"A little less managing. A little more peace of mind.",13,Ui.MUTED,false));Ui.gap(this,b,14);LinearLayout actions=Ui.row(this);weighted(actions,Ui.button(this,"Scan tag",this::scan,true));weighted(actions,Ui.button(this,"+ New order",this::newOrder,false));b.addView(actions);Ui.gap(this,b,13);
        int received=0,working=0,ready=0;for(int i=0;i<orders.length();i++){JSONObject o=orders.optJSONObject(i);if(Records.localDay(o.optString("createdAt")).equals(Records.today()))received++;if(o.optString("status").equals("Ready"))ready++;if(Arrays.asList("Received","Processing").contains(o.optString("status")))working++;}
        LinearLayout stats1=Ui.row(this);stat(stats1,"Today's orders",String.format(Locale.ROOT,"%02d",received),"Every garment accounted for");stat(stats1,"In the works",String.format(Locale.ROOT,"%02d",working),"A little care in progress");b.addView(stats1);LinearLayout stats2=Ui.row(this);stat(stats2,"Ready for pickup",String.format(Locale.ROOT,"%02d",ready),"Fresh, folded and ready");stat(stats2,"Collected today",Records.money(Records.collected(state,Records.today(),Records.today())),"Actual payments received");b.addView(stats2);Ui.gap(this,b,11);b.addView(Ui.text(this,"Recent orders",19,Ui.INK,true));Ui.gap(this,b,13);
        if(orders.length()==0){LinearLayout empty=Ui.card(this);empty.addView(Ui.text(this,"Ready for your first order",19,Ui.INK,true));empty.addView(Ui.text(this,"Choose a customer, add garments and create the bill. Each piece gets its own scannable QR tag.",13,Ui.MUTED,false));empty.addView(Ui.button(this,"Create an order",this::newOrder,false));b.addView(empty);}else for(int i=0;i<Math.min(5,orders.length());i++){JSONObject order=orders.optJSONObject(i);JSONObject customer=Records.customer(state,order.optString("customerId"));LinearLayout card=Ui.card(this);card.addView(Ui.text(this,customer==null?"Customer":customer.optString("name"),16,Ui.INK,true));card.addView(Ui.text(this,order.optString("id")+" · "+Records.pieces(order)+" garments · "+order.optString("status"),11,Ui.MUTED,false));Ui.gap(this,card,10);LinearLayout line=Ui.row(this);TextView due=Ui.text(this,"Due "+Records.date(order.optString("dueDate")),12,Ui.MUTED,false);line.addView(due,new LinearLayout.LayoutParams(0,-2,1));line.addView(Ui.text(this,Records.money(Records.total(order)),17,Ui.TEAL,true));card.addView(line);card.setOnClickListener(v->openOrder(order.optString("id")));b.addView(card);}b.addView(Ui.button(this,"View all orders",()->go("Orders"),true));Ui.gap(this,b,8);LinearLayout care=Ui.card(this);care.setBackground(Ui.background(Color.rgb(232,241,225),0,this,15));care.addView(Ui.text(this,"FRESH CLOTHES. HAPPY PEOPLE.",10,Ui.MUTED,true));Ui.gap(this,care,8);care.addView(Ui.text(this,"Your finest fabric caretaker.",20,Color.rgb(76,105,68),true));care.addView(Ui.text(this,"A little extra care, every single day.",13,Ui.MUTED,false));b.addView(care);return Ui.scroll(this,b);}
    private void weighted(LinearLayout row,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(Ui.dp(this,4),Ui.dp(this,5),Ui.dp(this,4),Ui.dp(this,5));row.addView(v,p);}
    private void stat(LinearLayout row,String label,String value,String note){LinearLayout card=Ui.card(this);card.addView(Ui.text(this,label,11,Ui.MUTED,false));Ui.gap(this,card,9);card.addView(Ui.text(this,value,25,Ui.INK,true));Ui.gap(this,card,10);card.addView(Ui.text(this,note,10,Ui.MUTED,false));card.setMinimumHeight(Ui.dp(this,129));weighted(row,card);}
    private void navigateBack(){if(!page.equals("Home")){go(Arrays.asList("Reports","Expenses","Settings").contains(page)?"More":"Home");}else finish();}
    @Override public boolean onKeyUp(int keyCode,android.view.KeyEvent event){if(Build.VERSION.SDK_INT<33&&keyCode==android.view.KeyEvent.KEYCODE_BACK&&!event.isCanceled()){navigateBack();return true;}return super.onKeyUp(keyCode,event);}
    private void manualTag(){LinearLayout b=body();EditText field=Ui.field(this,b,"Printed tag number","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);AlertDialog dialog=Ui.dialog(this,"Find a garment",b);b.addView(Ui.button(this,"Find garment",()->{String value=field.getText().toString();if(showTag(value))dialog.dismiss();},false));}
    private boolean showTag(String raw){String id=Records.parseTag(raw);JSONObject state=snapshot();Records.Tag found=null;JSONArray orders=Records.array(state,"orders");for(int i=0;i<orders.length()&&found==null;i++){JSONObject order=orders.optJSONObject(i);if(!id.startsWith(order.optString("id")+"-"))continue;for(Records.Tag tag:Records.tags(order))if(tag.id.equals(id)){found=tag;break;}}if(found==null){error("No garment matches this tag. Check the printed code and try again.");return false;}Records.Tag tag=found;JSONObject order=Records.order(state,tag.orderId);JSONObject customer=Records.customer(state,order.optString("customerId"));LinearLayout b=body();b.addView(Ui.text(this,tag.garment,22,Ui.INK,true));b.addView(Ui.text(this,(customer==null?"Customer":customer.optString("name"))+" · "+tag.orderId,14,Ui.MUTED,false));b.addView(Ui.text(this,tag.service+"\n"+tag.id,12,Ui.MUTED,false));int index=Arrays.asList(Records.STATUSES).indexOf(tag.status);Spinner status=Ui.spinner(this,b,"Garment status",Records.STATUSES,index);AlertDialog d=Ui.dialog(this,"Garment found",b);b.addView(Ui.button(this,"Save garment status",()->{try{if(save(Records.updateTag(snapshot(),tag.id,status.getSelectedItem().toString()))){d.dismiss();toast("Garment updated. The order follows all its pieces.");}}catch(Exception e){error(e.getMessage());}},false));b.addView(Ui.button(this,"Scan another tag",()->{d.dismiss();scan();},true));return true;}
    public void chooseLogo(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,LOGO);}
    public void exportBackup(){if(store==null){error("Restore a valid backup before exporting records.");return;}PrintHelper.shareText(this,snapshot().toString(),"Laundry-Lounge-backup-"+Records.today()+".json","application/json");}
    public void restoreBackup(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/plain","application/octet-stream"});startActivityForResult(i,RESTORE);}
    public void clearRecords(){new AlertDialog.Builder(this).setTitle("Clear all records?").setMessage("This removes all customers, orders and expenses on this phone. Business settings and your logo are kept. Export a backup first.").setNegativeButton("Keep records",null).setPositiveButton("Clear all records",(d,w)->{JSONObject state=snapshot();Records.put(state,"customers",new JSONArray());Records.put(state,"orders",new JSONArray());Records.put(state,"expenses",new JSONArray());save(state);}).show();}
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(result!=RESULT_OK||intent==null)return;try{if(request==SCAN){if(intent.getBooleanExtra("manual",false))manualTag();else showTag(intent.getStringExtra("code"));}else if(request==LOGO){applyLogo(intent.getData());}else if(request==RESTORE){byte[] bytes=read(intent.getData(),32*1024*1024);JSONObject backup=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(!Records.validate(backup))throw new IllegalArgumentException("This is not a valid Laundry Lounge backup. Existing records have been kept.");new AlertDialog.Builder(this).setTitle("Restore this backup?").setMessage("Replace current records with "+Records.array(backup,"orders").length()+" orders and "+Records.array(backup,"customers").length()+" customers? Export your current backup first.").setNegativeButton("Cancel",null).setPositiveButton("Replace and restore",(d,w)->{if(store!=null)save(backup);else try{store=Store.restore(this,backup);page="Home";render();}catch(Exception e){error(e.getMessage());}}).show();}}catch(Exception e){error(e.getMessage());}}
    private byte[] read(Uri uri,int limit)throws Exception{try(InputStream input=getContentResolver().openInputStream(uri);ByteArrayOutputStream output=new ByteArrayOutputStream()){if(input==null)throw new IllegalArgumentException("The selected file could not be opened.");byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(output.size()+n>limit)throw new IllegalArgumentException("Choose a smaller file. Nothing has been replaced.");output.write(buffer,0,n);}return output.toByteArray();}}
    private void applyLogo(Uri uri)throws Exception{byte[] bytes=read(uri,12*1024*1024);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1)throw new IllegalArgumentException("Choose a PNG, JPG or WebP logo image.");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>1024)options.inSampleSize*=2;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image==null)throw new IllegalArgumentException("The logo could not be opened.");int max=Math.max(image.getWidth(),image.getHeight());if(max>512)image=Bitmap.createScaledBitmap(image,Math.max(1,image.getWidth()*512/max),Math.max(1,image.getHeight()*512/max),true);ByteArrayOutputStream png=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,png);image.recycle();if(png.size()>2*1024*1024)throw new IllegalArgumentException("Choose a logo under 2 MB.");JSONObject state=snapshot();Records.put(state.optJSONObject("settings"),"logo","data:image/png;base64,"+Base64.encodeToString(png.toByteArray(),Base64.NO_WRAP));save(state);}
    private void recovery(String message){LinearLayout b=body();b.addView(Ui.title(this,"Your records need attention"));b.addView(Ui.text(this,message+"\nNothing has been silently replaced.",14,Ui.MUTED,false));b.addView(Ui.button(this,"Restore a backup",this::restoreBackup,false));b.addView(Ui.button(this,"Start with empty records",()->new AlertDialog.Builder(this).setTitle("Replace all records?").setMessage("This discards the current records on this phone. Only continue if you have a backup or do not need those records.").setNegativeButton("Cancel",null).setPositiveButton("Replace with empty",(d,w)->{try{store=Store.restore(this,Records.emptyStore());render();}catch(Exception e){error(e.getMessage());}}).show(),true));setContentView(Ui.scroll(this,b));}
}
